package com.crm.fees;
import com.crm.fees.config.SecurityConfig;import com.crm.fees.controller.FeeCycleController;import com.crm.fees.service.*;import com.crm.fees.exception.GlobalExceptionHandler;import com.crm.security.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import org.springframework.context.annotation.*;import org.springframework.mock.web.MockServletContext;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import org.springframework.test.web.servlet.MockMvc;import java.time.Instant;import java.util.List;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
/** Real filters and MVC validation; mocked Identity result and domain services, no database/network. */
class FeeCycleSecurityTest {
 AnnotationConfigWebApplicationContext context;MockMvc mvc;AccountValidationClient validation;FeeCycleService service;FeeReportService reports;
 @Configuration @EnableWebMvc static class Beans {
 @Bean jakarta.persistence.EntityManagerFactory entityManagerFactory(){return mock(jakarta.persistence.EntityManagerFactory.class);}
 @Bean AccountValidationClient validation(){return mock(AccountValidationClient.class);}@Bean JwtAuthenticationFilter jwt(AccountValidationClient c){return new JwtAuthenticationFilter(c);}@Bean RestAuthenticationEntryPoint entry(){return new RestAuthenticationEntryPoint();}@Bean CustomAccessDeniedHandler denied(){return new CustomAccessDeniedHandler();}
 @Bean FeeCycleService cycle(){return mock(FeeCycleService.class);}@Bean FeeReportService reports(){return mock(FeeReportService.class);}@Bean FeeCycleController controller(FeeCycleService c,FeeReportService r){return new FeeCycleController(c,r);}@Bean GlobalExceptionHandler errors(){return new GlobalExceptionHandler();}}
 @BeforeEach void setup(){context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.register(Beans.class,SecurityConfig.class);context.refresh();validation=context.getBean(AccountValidationClient.class);service=context.getBean(FeeCycleService.class);reports=context.getBean(FeeReportService.class);mvc=webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",jakarta.servlet.Filter.class)).build();}
 @AfterEach void close(){context.close();org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 void role(String r){when(validation.validate(any())).thenReturn(new AccountValidationResult(AccountValidationResult.Status.VALID,new JwtService.AccessTokenClaims(42,"synthetic",List.of(r),Instant.now().plusSeconds(3600))));}
 @ParameterizedTest @ValueSource(strings={"EMPLOYEE","CLIENT","ADMIN","SUPER_ADMIN"}) void cycleReadsAndExportsHaveAdministrativeRbac(String r)throws Exception{role(r);boolean admin=r.equals("ADMIN")||r.equals("SUPER_ADMIN");for(String path:List.of("/offerings","/offerings/7/tariffs","/offerings/7/times?from=2026-01-01&to=2026-01-31","/report?from=2026-01-01&to=2026-01-31","/report.csv?from=2026-01-01&to=2026-01-31")){var result=mvc.perform(get("/api/fees/cycle"+path).header("Authorization","Bearer synthetic")).andExpect(status().is(admin?200:403));if(admin)result.andExpect(header().string("Cache-Control","no-store"));}if(!admin)verifyNoInteractions(service,reports);}
 @ParameterizedTest @ValueSource(strings={"EMPLOYEE","CLIENT"}) void noPersonalFinancialWrites(String r)throws Exception{role(r);for(String path:List.of("/offerings","/offerings/7/tariffs","/offerings/7/times","/times/9/cancel","/times/9/record-fee"))mvc.perform(post("/api/fees/cycle"+path).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put("/api/fees/cycle/tariffs/8").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(patch("/api/fees/cycle/tariffs/8/active").contentType("application/json").content("{\"active\":false}")).andExpect(status().isForbidden());verifyNoInteractions(service,reports);}
 @Test void invalidSessionIs401()throws Exception{when(validation.validate(any())).thenReturn(AccountValidationResult.invalid());mvc.perform(get("/api/fees/cycle/offerings")).andExpect(status().isUnauthorized());verifyNoInteractions(service);}
 @Test void unavailableIdentityFails503()throws Exception{when(validation.validate(any())).thenReturn(AccountValidationResult.unavailable());mvc.perform(get("/api/fees/cycle/offerings")).andExpect(status().isServiceUnavailable());verifyNoInteractions(service);}
 @Test void malformedNumbersDatesAndMissingParametersAre400()throws Exception{role("ADMIN");for(String path:List.of("/report","/report?from=invalid&to=2026-01-31","/offerings?page=oops"))mvc.perform(get("/api/fees/cycle"+path)).andExpect(status().isBadRequest());mvc.perform(post("/api/fees/cycle/offerings/7/tariffs").contentType("application/json").content("{\"rate\":1.234,\"validFrom\":\"2026-01-01\",\"active\":true}")).andExpect(status().isBadRequest());mvc.perform(post("/api/fees/cycle/offerings/7/tariffs").contentType("application/json").content("{\"rate\":1,\"validFrom\":\"bad-date\",\"active\":true}")).andExpect(status().isBadRequest());verifyNoInteractions(service,reports);}
 @Test void bearerIsForwardedAndNoTargetIdentityAcceptedByTimeContract()throws Exception{role("ADMIN");mvc.perform(post("/api/fees/cycle/offerings").header("Authorization","Bearer synthetic").contentType("application/json").content("{\"title\":\"Work\",\"employeeId\":\"101\",\"customerId\":\"202\",\"currency\":\"TND\"}")).andExpect(status().isOk());verify(service).createOffering(any(),eq("Bearer synthetic"));}
 @Test void stateAndRemoteErrorsPreserveStatusWithoutPrivateBody()throws Exception{role("ADMIN");for(int code:List.of(401,403,404,409,502,503)){doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.valueOf(code),"synthetic-private")).when(service).offerings(any(),anyInt());mvc.perform(get("/api/fees/cycle/offerings")).andExpect(status().is(code)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("synthetic-private"))));}}
}
